def transform(g):
    col=1
    cells=[(r,c) for r in range(len(g)) for c in range(len(g[0])) if g[r][c]==col]
    r0=min(r for r,c in cells); c0=min(c for r,c in cells)
    mask=sorted((r-r0,c-c0) for r,c in cells)
    H,W=len(g),len(g[0])
    out=[row[:] for row in g]
    for r in range(H):
        for c in range(W):
            if all(0<=r+dr<H and 0<=c+dc<W and g[r+dr][c+dc]==0 for dr,dc in mask):
                for dr,dc in mask: out[r+dr][c+dc]=col
    return out
